    "prem.sub":        { en:"Try Premium free for 14 days.", es:"Prueba Premium gratis 14 días.", fr:"Essayez Premium gratuitement pendant 14 jours.", pt:"Experimente o Premium grátis por 14 dias.", ar:"جرّب Premium مجانًا لمدة 14 يومًا.", zh:"免费试用 Premium 14 天。", nl:"Probeer Premium 14 dagen gratis.", de:"Teste Premium 14 Tage kostenlos.", hi:"Premium को 14 दिन मुफ़्त आज़माएँ।", bn:"Premium ১৪ দিন ফ্রি ব্যবহার করে দেখুন।", id:"Coba Premium gratis selama 14 hari.", ur:"Premium کو 14 دن مفت آزمائیں۔", tr:"Premium’u 14 gün ücretsiz dene.", it:"Prova Premium gratis per 14 giorni.", ja:"Premiumを14日間無料でお試し。", ko:"Premium을 14일 동안 무료로 사용해 보세요.", ru:"Попробуйте Premium бесплатно 14 дней." },
    "prem.f1":         { en:"Unlimited AI Counting", es:"Conteo con IA ilimitado", fr:"Comptage IA illimité", pt:"Contagem com IA ilimitada", ar:"حساب غير محدود بالذكاء الاصطناعي", zh:"无限次 AI 计分", nl:"Onbeperkt AI-tellen", de:"Unbegrenztes KI-Zählen", hi:"असीमित AI काउंटिंग", bn:"সীমাহীন AI কাউন্টিং", id:"Penghitungan AI tanpa batas", ur:"لامحدود AI کاؤنٹنگ", tr:"Sınırsız yapay zekâ sayma", it:"Conteggio con IA illimitato", ja:"AIカウント無制限", ko:"무제한 AI 계산", ru:"Неограниченный подсчёт через ИИ" },
