    "prem.f3":         { en:"All Themes & Animations", es:"Todos los temas y animaciones", fr:"Tous les thèmes et animations", pt:"Todos os temas e animações", ar:"كل المظاهر والمؤثرات", zh:"全部主题与动画", nl:"Alle thema’s en animaties", de:"Alle Designs und Animationen", hi:"सभी थीम और एनिमेशन", bn:"সব থিম ও অ্যানিমেশন", id:"Semua tema & animasi", ur:"تمام تھیمز اور اینیمیشنز", tr:"Tüm temalar ve animasyonlar", it:"Tutti i temi e le animazioni", ja:"すべてのテーマとアニメーション", ko:"모든 테마와 애니메이션", ru:"Все темы и анимации" },
    "prem.f6":         { en:"Share Games", es:"Compartir partidas", fr:"Partager des parties", pt:"Compartilhar partidas", ar:"مشاركة المباريات", zh:"分享比赛", nl:"Spellen delen", de:"Spiele teilen", hi:"गेम शेयर करें", bn:"খেলা শেয়ার করুন", id:"Bagikan permainan", ur:"گیمز شیئر کریں", tr:"Oyunları paylaş", it:"Condividere partite", ja:"ゲームを共有", ko:"게임 공유", ru:"Обмен играми" },
    "prem.f7":         { en:"Widgets & Live Activity", es:"Widgets y Actividad en vivo", fr:"Widgets et activité en direct", pt:"Widgets e Atividade ao vivo", ar:"عناصر واجهة ونشاط مباشر", zh:"小组件与实时活动", nl:"Widgets en Live Activiteit", de:"Widgets und Live-Aktivität", hi:"विजेट और लाइव एक्टिविटी", bn:"উইজেট ও লাইভ অ্যাক্টিভিটি", id:"Widget & Aktivitas Langsung", ur:"ویجٹس اور لائیو ایکٹیویٹی", tr:"Widget’lar ve Canlı Etkinlik", it:"Widget e Attività in tempo reale", ja:"ウィジェットとライブアクティビティ", ko:"위젯과 실시간 액티비티", ru:"Виджеты и Live Activity" },
    "prem.f8":         { en:"Custom Backgrounds", es:"Fondos personalizados", fr:"Fonds personnalisés", pt:"Fundos personalizados", ar:"خلفيات مخصّصة", zh:"自定义背景", nl:"Eigen achtergronden", de:"Eigene Hintergründe", hi:"कस्टम बैकग्राउंड", bn:"কাস্টম ব্যাকগ্রাউন্ড", id:"Latar belakang kustom", ur:"کسٹم بیک گراؤنڈز", tr:"Özel arka planlar", it:"Sfondi personalizzati", ja:"カスタム背景", ko:"맞춤 배경", ru:"Свои фоны" },
