    "inv.liveTournament": { en:"Follow the tournament live", es:"Sigue el torneo en vivo", fr:"Suivez le tournoi en direct", pt:"Acompanhe o torneio ao vivo", ar:"تابع البطولة مباشرة", zh:"实时跟看这场赛事", nl:"Volg het toernooi live", de:"Verfolge das Turnier live", hi:"टूर्नामेंट लाइव देखें", bn:"টুর্নামেন্ট লাইভ দেখুন", id:"Ikuti turnamen secara langsung", ur:"ٹورنامنٹ لائیو دیکھیں", tr:"Turnuvayı canlı izle", it:"Segui il torneo in diretta", ja:"トーナメントをライブで観戦", ko:"토너먼트를 실시간으로 보기", ru:"Следите за турниром в прямом эфире" },
    "inv.liveGame": { en:"Follow the game live", es:"Sigue la partida en vivo", fr:"Suivez la partie en direct", pt:"Acompanhe a partida ao vivo", ar:"تابع اللعبة مباشرة", zh:"实时跟看这局比赛", nl:"Volg het spel live", de:"Verfolge das Spiel live", hi:"गेम लाइव देखें", bn:"খেলা লাইভ দেখুন", id:"Ikuti permainan secara langsung", ur:"گیم لائیو دیکھیں", tr:"Oyunu canlı izle", it:"Segui la partita in diretta", ja:"ゲームをライブで観戦", ko:"게임을 실시간으로 보기", ru:"Следите за игрой в прямом эфире" },
    "inv.waitTournament": { en:"A tournament is waiting for you", es:"Un torneo te está esperando", fr:"Un tournoi vous attend", pt:"Um torneio está esperando por você", ar:"هناك بطولة تنتظرك", zh:"有一场赛事在等你", nl:"Er staat een toernooi voor je klaar", de:"Ein Turnier wartet auf dich", hi:"एक टूर्नामेंट आपका इंतज़ार कर रहा है", bn:"একটি টুর্নামেন্ট আপনার জন্য অপেক্ষা করছে", id:"Sebuah turnamen menunggu Anda", ur:"ایک ٹورنامنٹ آپ کا انتظار کر رہا ہے", tr:"Seni bir turnuva bekliyor", it:"Un torneo ti sta aspettando", ja:"トーナメントが届いています", ko:"토너먼트가 기다리고 있습니다", ru:"Вас ждёт турнир" },
    "inv.waitGame": { en:"A game is waiting for you", es:"Una partida te está esperando", fr:"Une partie vous attend", pt:"Uma partida está esperando por você", ar:"هناك لعبة تنتظرك", zh:"有一局比赛在等你", nl:"Er staat een spel voor je klaar", de:"Ein Spiel wartet auf dich", hi:"एक गेम आपका इंतज़ार कर रहा है", bn:"একটি খেলা আপনার জন্য অপেক্ষা করছে", id:"Sebuah permainan menunggu Anda", ur:"ایک گیم آپ کا انتظار کر رہا ہے", tr:"Seni bir oyun bekliyor", it:"Una partita ti sta aspettando", ja:"ゲームが届いています", ko:"게임이 기다리고 있습니다", ru:"Вас ждёт игра" },
    "inv.hint": { en:"In the app, tap <strong>Share live</strong> → <strong>Enter code</strong>.", es:"En la app, toca <strong>Compartir en vivo</strong> → <strong>Entrar con código</strong>.", fr:"Dans l’app, touchez <strong>Partager en direct</strong> → <strong>Saisir un code</strong>.", pt:"No app, toque em <strong>Compartilhar ao vivo</strong> → <strong>Inserir código</strong>.", ar:"في التطبيق، اضغط <strong>مشاركة مباشرة</strong> ← <strong>إدخال رمز</strong>.", zh:"在应用里，点击<strong>实时分享</strong> → <strong>输入代码</strong>。", nl:"Tik in de app op <strong>Live delen</strong> → <strong>Code invoeren</strong>.", de:"Tippe in der App auf <strong>Live teilen</strong> → <strong>Code eingeben</strong>.", hi:"ऐप में <strong>लाइव शेयर करें</strong> → <strong>कोड दर्ज करें</strong> पर टैप करें।", bn:"অ্যাপে <strong>লাইভ শেয়ার</strong> → <strong>কোড লিখুন</strong> এ ট্যাপ করুন।", id:"Di aplikasi, ketuk <strong>Bagikan langsung</strong> → <strong>Masukkan kode</strong>.", ur:"ایپ میں <strong>لائیو شیئر کریں</strong> ← <strong>کوڈ درج کریں</strong> پر ٹیپ کریں۔", tr:"Uygulamada <strong>Canlı paylaş</strong> → <strong>Kod gir</strong>’e dokun.", it:"Nell’app, tocca <strong>Condividi in diretta</strong> → <strong>Inserisci codice</strong>.", ja:"アプリで<strong>ライブで共有</strong> → <strong>コードを入力</strong>をタップします。", ko:"앱에서 <strong>실시간 공유</strong> → <strong>코드 입력</strong>을 탭하세요.", ru:"В приложении нажмите <strong>Показать в эфире</strong> → <strong>Ввести код</strong>." },


